import React, { useEffect, useState } from "react";
import { fetchProducts, fetchFiltered } from "../api";
import ProductCard from "./ProductCard";

export default function ProductList() {
  const [products, setProducts] = useState([]);
  const [category, setCategory] = useState("");
  const [sort, setSort] = useState("");

  // Load all products on startup
  useEffect(() => {
    fetchProducts().then((data) => {
      if (Array.isArray(data)) setProducts(data);
    });
  }, []);

  // Filter by category
  const handleFilter = async (e) => {
    const selected = e.target.value;
    setCategory(selected);

    if (selected === "") {
      fetchProducts().then((data) => setProducts(data));
      return;
    }

    const filtered = await fetchFiltered(selected);
    if (Array.isArray(filtered)) setProducts(filtered);
  };

  // Sort products
  const handleSort = (e) => {
    const value = e.target.value;
    setSort(value);

    let sorted = [...products];

    if (value === "low") sorted.sort((a, b) => a.price - b.price);
    if (value === "high") sorted.sort((a, b) => b.price - a.price);

    setProducts(sorted);
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Products</h2>

      {/* Filter + Sort Row */}
      <div style={styles.controls}>
        <select value={category} onChange={handleFilter} style={styles.select}>
          <option value="">All categories</option>
          <option value="Electronics">Electronics</option>
          <option value="Fashion">Fashion</option>
          <option value="Accessories">Accessories</option>
          <option value="Home Appliances">Home Appliances</option>
          <option value="Furniture">Furniture</option>
          <option value="Sports">Sports</option>
          <option value="Beauty">Beauty</option>
        </select>

        <select value={sort} onChange={handleSort} style={styles.select}>
          <option value="">Sort</option>
          <option value="low">Price: Low → High</option>
          <option value="high">Price: High → Low</option>
        </select>
      </div>

      {/* Product Grid */}
      <div style={styles.grid}>
        {products.map((p) => (
          <ProductCard key={p.id} product={p} />
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px 40px",
  },
  heading: {
    marginBottom: "18px",
    fontSize: "26px",
    fontWeight: "600",
  },
  controls: {
    display: "flex",
    gap: "15px",
    marginBottom: "20px",
  },
  select: {
    padding: "10px",
    borderRadius: "8px",
    border: "1px solid #ccc",
    fontSize: "15px",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(290px, 1fr))",
    gap: "24px",
  },
};
